// Normalize shipping_level to Lulu enum. Constrain Amazon to MAIL/EXPEDITED.
const j = $input.first().json || {};
function toLuluLevel(raw){
  const s = String(raw || '').trim().toUpperCase();
  if (!s) return null;
  const map = { MAIL:'MAIL', STANDARD:'MAIL', ECONOMY:'MAIL', PRIORITY_MAIL:'PRIORITY_MAIL', PRIORITY:'PRIORITY_MAIL', GROUND:'GROUND', GROUND_HD:'GROUND_HD', GROUND_HOME:'GROUND_HD', GROUND_BUS:'GROUND_BUS', GROUND_BUSINESS:'GROUND_BUS', EXPEDITED:'EXPEDITED', EXPRESS:'EXPRESS', OVERNIGHT:'EXPRESS', NEXT_DAY:'EXPRESS', NEXTDAY:'EXPRESS' };
  return map[s] || null;
}
// Only real shipping-level fields; do NOT use order IDs (amazonOrderId) as signal or D2C orders get MAIL.
const amazonSignal = [j.order?.ShipmentServiceLevelCategory,j.order?.ShipServiceLevel,j.ShipmentServiceLevelCategory,j.ShipServiceLevel,j.amazon_shipment_service_level,j.manifest?.order?.ShipmentServiceLevelCategory,j.manifest?.order?.ShipServiceLevel].find(Boolean);
const requested = j.shipping_tier || j.shippingTier || j.luluPayload?.shipping_level || j.printOptions?.shippingLevel || j.CONFIG?.defaults?.shippingLevel;
const candidate = toLuluLevel(requested) || 'MAIL';
const amazonText = String(amazonSignal || '').toUpperCase();
const amazonMapped = !amazonSignal ? null : ((amazonText.includes('EXPEDITED') || amazonText.includes('2-DAY') || amazonText.includes('2DAY') || amazonText.includes('PRIORITY') || amazonText.includes('OVERNIGHT') || amazonText.includes('EXPRESS')) ? 'EXPEDITED' : 'MAIL');
const shipping_level = amazonMapped || candidate;
return [{ json: { ...j, luluPayload: { ...(j.luluPayload || {}), shipping_level }, shippingLevelRequested: requested || null, shippingLevelSent: shipping_level } }];

// Canonical normalize node (active)
function isUrl(s){ return typeof s==='string' && /^https?:\/\//i.test(s); }
function firstNonEmpty(...vals){ for(const v of vals){ if(v===undefined||v===null) continue; if(typeof v==='string'){ if(v.trim()!=='') return v.trim(); } else return v; } }
function toAssetUrl(raw,assetBase){ if(!raw) return undefined; if(isUrl(raw)) return raw; const s=String(raw).trim(); if(!s||!assetBase) return undefined; return assetBase.replace(/\/$/,'') + '/' + s.replace(/^\/+/, ''); }

const root=$input.item.json||{};
const CONFIG=root.CONFIG||{};
const backendUrl='https://admin.littleherolabs.com';
const http=this.helpers.httpRequest;

const preOrderId=firstNonEmpty(root.orderId,root.order_id,root.amazon_order_id,root.amazonOrderId,root.product_info?._root_order_id) || '';
const rawManifest3Ref=firstNonEmpty(root.manifest3Key,root.three_manifest_url,root.manifest3Url,root.manifestUrl);
let manifest3Ref=(rawManifest3Ref && /1-manifest\.json/i.test(String(rawManifest3Ref))) ? (preOrderId ? `book-mvp-simple-adventure/orders/${preOrderId}/manifests/3-manifest.json` : null) : rawManifest3Ref;
if(!manifest3Ref && preOrderId) manifest3Ref=`book-mvp-simple-adventure/orders/${preOrderId}/manifests/3-manifest.json`;

let manifest={};
if(manifest3Ref){
  try{
    const url=isUrl(manifest3Ref)?String(manifest3Ref):`${backendUrl}/api/manifests/${manifest3Ref}`;
    const resp=await http({method:'GET',url,json:true,ignoreHttpStatusErrors:true,returnFullResponse:true});
    const status=Number(resp?.statusCode||resp?.status||200);
    const body=resp?.body!==undefined?resp.body:resp;
    const candidate=body?.manifest||body?.data?.manifest||body;
    if(status>=200&&status<300&&candidate&&typeof candidate==='object'&&!candidate.error) manifest=candidate;
  }catch(e){}
}

const orderId=firstNonEmpty(preOrderId,manifest.orderId,manifest.order_id,manifest.amazon_order_id,manifest.amazonOrderId,String(manifest3Ref||'').match(/orders\/([^/]+)\//)?.[1]);
if(!orderId) throw new Error(`W4.1: missing orderId (manifest3Ref=${manifest3Ref||'none'})`);

const assetBase=(CONFIG.defaults?.trimIn?.assetBase||'https://admin.littleherolabs.com/api/assets/').replace(/\/$/,'');
const pngGen=manifest.pngGeneration||root.pngGeneration||{};
let pagesR2=pngGen.pages||manifest.pages||root.pages||{};
let pagesCF=pngGen.pagesWithCloudflare||manifest.pagesWithCloudflare||root.pagesWithCloudflare||{};
if(!pagesR2||Array.isArray(pagesR2)) pagesR2={};
if(!pagesCF||Array.isArray(pagesCF)) pagesCF={};

const keyedR2=Object.keys(pagesR2).filter(k=>k==='p00'||k==='p00_dedication'||/^p\d{2,}$/.test(k));
const keyedCF=Object.keys(pagesCF).filter(k=>k==='p00'||k==='p00_dedication'||/^p\d{2,}$/.test(k));
const allKeys=[...new Set([...keyedR2,...keyedCF])];
const hasDedication=allKeys.includes('p00')||allKeys.includes('p00_dedication');
const nums=[...new Set(allKeys.filter(k=>/^p\d{2,}$/.test(k)).map(k=>Number(k.slice(1))))].sort((a,b)=>a-b);
const legacyPageImageUrls=Array.isArray(root.pageImageUrls)?root.pageImageUrls:(Array.isArray(manifest.pageImageUrls)?manifest.pageImageUrls:[]);

let requiredKeys=[];
if(nums.length>0){
  const start=hasDedication?0:Math.max(1,nums[0]);
  const end=nums[nums.length-1];
  for(let n=start;n<=end;n++) requiredKeys.push('p'+String(n).padStart(2,'0'));
}

let pageImageUrls=[];
if(requiredKeys.length>0){
  for(const key of requiredKeys){
    const keyR2=key==='p00'?(pagesR2.p00?'p00':(pagesR2.p00_dedication?'p00_dedication':'p00')):key;
    let url;
    const raw=pagesR2[keyR2];
    if(typeof raw==='string'&&raw.trim()) url=isUrl(raw)?raw:toAssetUrl(raw,assetBase);
    else if(raw&&typeof raw==='object'){ const c=raw.r2Key||raw.url||raw.path||raw.key||''; if(c) url=isUrl(c)?c:toAssetUrl(c,assetBase); }
    if(!url){
      const keyCF=key==='p00'?(pagesCF.p00?'p00':(pagesCF.p00_dedication?'p00_dedication':'p00')):key;
      const cf=pagesCF[keyCF]||pagesCF[key];
      url=typeof cf==='string'?cf:(cf?.cloudflareImageUrl||cf?.url);
    }
    if(!url) throw new Error(`W4.1: missing page ${key}`);
    pageImageUrls.push(String(url));
  }
}else if(legacyPageImageUrls.length>0){
  pageImageUrls=legacyPageImageUrls.map(v=>String(v));
}else{
  throw new Error(`W4.1: sibling ${orderId} missing page assets (manifest3Ref=${manifest3Ref||'none'})`);
}

const bust=encodeURIComponent(String(manifest.runStamp||manifest.generatedAt||orderId||Date.now()));
pageImageUrls=pageImageUrls.map(u=>u+(u.includes('?')?'&':'?')+'v='+bust);

const expectedPageCount=pageImageUrls.length||17;
const pdfFilename=`interior_${orderId}.pdf`;
const pdfR2Key=`book-mvp-simple-adventure/orders/${orderId}/${pdfFilename}`;
const coverPdfR2Key=manifest.coverPdfR2Key||manifest.pdfGeneration?.coverPdf||root.coverPdfR2Key||`book-mvp-simple-adventure/orders/${orderId}/cover_${orderId}.pdf`;
let shippingAddress=manifest.shippingAddress||manifest.shipping_address||root.shipping_address||root.shippingAddress||{};

if(!shippingAddress?.phone_number&&!shippingAddress?.phone){
  try{
    const m1Ref=firstNonEmpty(root.one_manifest_url,`book-mvp-simple-adventure/orders/${orderId}/manifests/1-manifest.json`);
    const m1Url=isUrl(m1Ref)?String(m1Ref):`${backendUrl}/api/manifests/${m1Ref}`;
    const m1=await http({method:'GET',url:m1Url,json:true,ignoreHttpStatusErrors:true});
    if(m1&&typeof m1==='object'&&!m1.error){
      const sa=m1.order?.orderDetails?.shippingAddress||m1.shippingAddress||{};
      if(sa.phone||sa.phone_number||sa.phoneNumber){
        shippingAddress={...shippingAddress,name:shippingAddress.name||sa.name,street1:shippingAddress.street1||sa.address||sa.street1,city:shippingAddress.city||sa.city,state_code:shippingAddress.state_code||(sa.state||'').toUpperCase(),postcode:shippingAddress.postcode||sa.zip||sa.postcode,country_code:shippingAddress.country_code||(sa.country||sa.country_code||'US').toUpperCase(),phone_number:sa.phone||sa.phone_number||sa.phoneNumber,email:shippingAddress.email||sa.email};
      }
    }
  }catch(e){}
}

const coverPreviewRef=firstNonEmpty(
  manifest.coverImageUrl,
  Array.isArray(manifest.coverImageUrls)?manifest.coverImageUrls[0]:undefined,
  manifest.coverPngR2Key,
  manifest.pngGeneration?.coverSpreadImage,
  root.coverImageUrl,
  Array.isArray(root.coverImageUrls)?root.coverImageUrls[0]:undefined,
  root.coverPngR2Key,
  root.pngGeneration?.coverSpreadImage,
  'book-mvp-simple-adventure/orders/'+orderId+'/preview-images/cover-spread.png'
);
const coverPreviewUrlBase=toAssetUrl(coverPreviewRef,assetBase);
const coverPreviewUrl=coverPreviewUrlBase?coverPreviewUrlBase+(coverPreviewUrlBase.includes('?')?'&':'?')+'v='+bust:null;
if(!coverPreviewUrl) throw new Error('W4.1: missing cover preview for '+orderId);
const pageLabels=Array.from({ length: expectedPageCount }, (_, index) => 'p'+String(index).padStart(2,'0'));
const childName=(root.character_specs?.childName||manifest.character_specs?.childName||'Book').toString().trim()||'Book';
return { json:{...root,...manifest,CONFIG,orderId,pageImageUrls,pageLabels,coverPreviewUrl,expectedPageCount,pdfFilename,pdfR2Key,coverPdfR2Key,shippingAddress,childName} };

// Config + Validate Sibling Group — add CONFIG, validate, emit N items (one per sibling)
// SECURITY: never commit real secrets in workflow exports.
const inputItems = $input.all();
const root = $input.first()?.json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;

function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s !== '') return s;
    } else {
      return v;
    }
  }
}

function deriveRootOrderId(id) {
  if (!id) return id;
  const m = String(id).match(/^(.+?)-item-/);
  return m ? m[1] : id;
}

function extractSiblingGroup(candidate) {
  if (!candidate || typeof candidate !== 'object') return null;
  const direct = candidate.siblingGroup || candidate.siblingOrders || candidate.orders;
  if (Array.isArray(direct) && direct.length) return direct;
  const nestedBody = candidate.body && typeof candidate.body === 'object' ? extractSiblingGroup(candidate.body) : null;
  if (nestedBody) return nestedBody;
  const nestedData = candidate.data && typeof candidate.data === 'object' ? extractSiblingGroup(candidate.data) : null;
  if (nestedData) return nestedData;
  const nestedPayload = candidate.payload && typeof candidate.payload === 'object' ? extractSiblingGroup(candidate.payload) : null;
  if (nestedPayload) return nestedPayload;
  return null;
}

const CONFIG = {
  pdfMonkey: { token: '2zpxHdmsse2ECXgVVtVR', templateId: '5539DDB4-EC78-4AE9-A3FB-DB1E7F8DD172', coverTemplateId: 'D52F14C8-BBC3-4058-929F-195DFC707E75' },
  lulu: { apiBase: 'https://api.lulu.com', clientKey: '9b388aaa-f0c9-448d-b3d1-8561a8cf2094', clientSecret: '3fsYZ7GbbXvdQhsOSxstzIbqdbdJMMtS', basicAuth: null },
  supabase: { projectUrl: 'https://mdnthwpcnphjnnblbvxk.supabase.co', serviceRoleKey: 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im1kbnRod3BjbnBoam5uYmxidnhrIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2MDUwMDc4MCwiZXhwIjoyMDc2MDc2NzgwfQ.wNVQ3U2nWTGu8VsuXKasWOCxVhpca5x42wSapQDinGs' },
  r2: { bucket: 'little-hero-orders', endpointHost: '3daae940fcb6fc5b8bbd9bb8fcc62854.r2.cloudflarestorage.com', region: 'auto', accessKeyId: '320e3b8228c5ff7bd2395043886f03d3', secretAccessKey: 'a1ba025ddbe2d8ef7032d2d6635dce3b6fbc4bdbf9c19c68d0b0bd566c989572' },
  backendApiToken: 'e41d510ce6ed6e9c7f602fea860f2591cc7ec75fe63e448336a97c4b73898646',
  renderer: {
    apiBase: 'https://renderer-eta.vercel.app'
  },
  defaults: { debug: false, testMode: false, podPackageId: '0850X0850FCPRESS080CW444MXX', trimIn: { w: 8.5, h: 8.5, assetBase: 'https://admin.littleherolabs.com/api/assets/', podPackageId: null }, bleedIn: { w: 8.75, h: 8.75 }, print: { color: 'premium-color', stock: '80#-text', binding: 'saddle-stitch', coverFinish: 'matte' }, quantity: 1, shippingLevel: 'MAIL' }
};
try { const k = CONFIG.lulu?.clientKey || ''; const s = CONFIG.lulu?.clientSecret || ''; CONFIG.lulu.basicAuth = 'Basic ' + Buffer.from(`${k}:${s}`).toString('base64'); } catch (e) {}

let siblingGroup = extractSiblingGroup(body) || extractSiblingGroup(root);

if ((!Array.isArray(siblingGroup) || siblingGroup.length === 0) && inputItems.length > 1) {
  const groupedItems = inputItems
    .map((item) => item?.json || {})
    .map((item) => item.body && typeof item.body === 'object' ? item.body : item)
    .filter((item) => Boolean(firstNonEmpty(item.orderId, item.order_id, item.amazon_order_id, item.amazonOrderId)));
  if (groupedItems.length) siblingGroup = groupedItems;
}

if (!Array.isArray(siblingGroup) || siblingGroup.length < 2) {
  const keys = Object.keys(body || {}).sort().join(', ') || 'none';
  const inputCount = Array.isArray(inputItems) ? inputItems.length : 0;
  const resolvedLength = Array.isArray(siblingGroup) ? siblingGroup.length : 0;
  throw new Error(`W4.1: siblingGroup must contain at least 2 items (resolved=${resolvedLength}, inputItems=${inputCount}, bodyKeys=${keys})`);
}

const rootGroupId = firstNonEmpty(
  body.rootOrderId,
  body.root_order_id,
  root.rootOrderId,
  root.root_order_id,
  siblingGroup[0]?.rootOrderId,
  siblingGroup[0]?.root_order_id,
  siblingGroup[0]?.product_info?._root_order_id,
  deriveRootOrderId(siblingGroup[0]?.orderId || siblingGroup[0]?.amazon_order_id || siblingGroup[0]?.amazonOrderId)
) || null;

for (let i = 0; i < siblingGroup.length; i++) {
  const s = siblingGroup[i];
  if (!s.orderId && !s.amazon_order_id) throw new Error(`W4.1: sibling ${i} missing orderId`);
  const addr = s.shipping_address || s.shippingAddress || siblingGroup[0].shipping_address || siblingGroup[0].shippingAddress;
  if (!addr?.phone_number && !addr?.phone) throw new Error(`W4.1: sibling ${i} missing shipping_address.phone_number`);
}

return siblingGroup.map(s => {
  const orderId = firstNonEmpty(s.orderId, s.order_id, s.amazon_order_id, s.amazonOrderId);
  const rootOrderId = firstNonEmpty(s.rootOrderId, s.root_order_id, rootGroupId, deriveRootOrderId(orderId));
  const manifest3Key = firstNonEmpty(
    s.manifest3Key,
    s.three_manifest_url,
    s.manifest3Url,
    s.manifestUrl,
    orderId ? `book-mvp-simple-adventure/orders/${orderId}/manifests/3-manifest.json` : null
  );
  const oneManifestUrl = firstNonEmpty(s.one_manifest_url, s.oneManifestUrl, s.oneManifestKey);
  return {
    json: {
      ...s,
      CONFIG,
      rootGroupId,
      rootOrderId,
      orderId,
      manifest3Key,
      one_manifest_url: oneManifestUrl || null
    }
  };
});

// Build pages_html for PDFMonkey at 8.75×8.75 in
const j=$input.item.json||{};
const pages=Array.isArray(j.pageImageUrls)?j.pageImageUrls:[];
if(!pages.length)throw new Error('No pageImageUrls');
const css=`
  <style>
    @page { size: 8.75in 8.75in; margin: 0; }
    html, body { margin:0; padding:0; }
    .page { width:8.75in; height:8.75in; page-break-after: always; }
    .bg { width:100%; height:100%; object-fit: cover; display:block; }
  </style>
`;
const pagesHtml=pages.map(url=>`<section class="page"><img class="bg" src="${url}" alt="" /></section>`).join('
');
return{json:{...j,pages_html:`${css}
${pagesHtml}`}};

// Presign Interior Assets: replace /api/assets/ proxy URLs with signed R2 URLs
// so PDFMonkey fetches directly from Cloudflare R2 edge (no Vercel proxy).
const item = $input.item.json || {};
const pagesHtml = item.pages_html;
if (!pagesHtml || typeof pagesHtml !== 'string') {
  throw new Error('[Presign Interior Assets] Missing pages_html');
}
const backendUrl = (item.CONFIG?.defaults?.trimIn?.assetBase || 'https://admin.littleherolabs.com/api/assets/').replace(/\/api\/assets\/?$/, '');
const url = `${backendUrl}/api/render/presign-page-assets`;
const http = this.helpers.httpRequest;
const token = item.CONFIG?.backendApiToken || '';
const headers = token ? { Authorization: `Bearer ${token}` } : {};
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
function jitter(max = 200) { return Math.floor(Math.random() * max); }
let lastErr = null;
for (let attempt = 1; attempt <= 3; attempt++) {
  try {
    const res = await http({ method: 'POST', url, headers, body: { html: pagesHtml, expiresInSeconds: 21600 }, json: true, timeout: 30000 });
    if (res?.html && typeof res.html === 'string') {
      return { json: { ...item, pages_html: res.html } };
    }
    throw new Error('Presign endpoint returned no html');
  } catch (e) {
    lastErr = e;
    if (attempt < 3) await sleep(300 + attempt * 300 + jitter());
  }
}
const orderId = item.orderId || item.amazonOrderId || 'UNKNOWN';
throw new Error(`[Presign Interior Assets] Failed after 3 attempts (orderId=${orderId}): ${lastErr?.message || lastErr}`);

const d=$input.item.json;
const tpl=d.CONFIG?.pdfMonkey?.templateId;
if(!tpl)throw new Error('Missing PDFMonkey templateId');
return{json:{...d,document:{document_template_id:tpl,status:'pending',meta:{_filename:d.pdfFilename},payload:{pages_html:d.pages_html}}}};

// Reattach context + Poll PDFMonkey until ready
const httpResp=$input.item.json||{};
let ctx={}; try{ctx=($items('Build Pages HTML (8.75in)',0,$runIndex)?.[0]?.json)||{};}catch{}
if(!ctx.orderId)try{ctx=($items('Validate & Normalize Per Sibling',0,$runIndex)?.[0]?.json)||ctx;}catch{}
const doc=httpResp.document||httpResp.data||httpResp;
const docId=doc.id||doc.data?.id; if(!docId)throw new Error('PDFMonkey missing id');
const token=ctx.CONFIG?.pdfMonkey?.token; if(!token)throw new Error('Missing token');
const http=this.helpers.httpRequest; const AUTH={Authorization:`Bearer ${token}`};
let status=doc.status||'queued'; let downloadUrl=doc.download_url||null;
async function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
for(let a=0;a<40;a++){
  if(status==='success'&&downloadUrl)break;
  try{const r=await http({method:'GET',url:`https://api.pdfmonkey.io/api/v1/documents/${docId}`,json:true,headers:AUTH});
  const d=r?.document||r?.data||r; status=d?.status||status; downloadUrl=d?.download_url||d?.file_url||downloadUrl;
  if(status==='error'||status==='failure')throw new Error('PDFMonkey error: '+(d?.failure_cause||status));}
  catch(e){if(e.message.includes('PDFMonkey error'))throw e; await sleep(1500); continue;}
  await sleep(1200+Math.min(a*150,3800));
}
if(status!=='success'||!downloadUrl)throw new Error('PDF not ready');
return{json:{...ctx,pdfMonkeyDocumentId:docId,pdfDownloadUrl:downloadUrl,pdfR2Key:ctx.pdfR2Key}};

// Build cover HTML for PDFMonkey
const j=$input.item.json||{};
const cfg=j.CONFIG||{};
const assetBase=(cfg.defaults?.trimIn?.assetBase||'https://admin.littleherolabs.com/api/assets/').replace(/\/+$/,'');
const orderId=j.orderId||'unknown';
const runStamp=j.runStamp||new Date().toISOString();
function isUrl(s){return typeof s==='string'&&/^https?:\/\//i.test(s);}
function toAssetUrl(p){if(!p)return undefined;if(isUrl(p))return p; return `${assetBase}/${String(p).replace(/^\/+/,'')}`;}
let coverRef=j.coverImageUrl||(Array.isArray(j.coverImageUrls)&&j.coverImageUrls[0])||j.coverPngR2Key||j.pngGeneration?.coverSpreadImage||`book-mvp-simple-adventure/orders/${orderId}/preview-images/cover-spread.png`;
const coverUrl=(toAssetUrl(coverRef)||'')+(coverRef?`?v=${encodeURIComponent(runStamp)}`:'');
if(!coverUrl)throw new Error('Missing cover image');
const css=`\n  <style>\n    @page { size: 17.25in 8.75in; margin: 0; }\n    html, body { margin:0; padding:0; }\n    .page { width:17.25in; height:8.75in; page-break-after: always; overflow:hidden; }\n    .bg { width:100%; height:100%; display:block; object-fit:cover; }\n  </style>\n`;
const html=`<section class="page"><img class="bg" src="${coverUrl}" alt="" /></section>`;
return{json:{...j,cover_html:`${css}\n${html}`,coverPdfFilename:`cover_${orderId}.pdf`}};

// Presign Cover Assets: replace /api/assets/ proxy URLs with signed R2 URLs
// so PDFMonkey fetches directly from Cloudflare R2 edge (no Vercel proxy).
const item = $input.item.json || {};
const orderId = item.orderId || item.amazonOrderId || item.amazon_order_id || '';
const coverHtml = item.cover_html;
const token = item.CONFIG?.backendApiToken || '';
const backendUrl = (item.CONFIG?.defaults?.trimIn?.assetBase || 'https://admin.littleherolabs.com/api/assets/').replace(/\/api\/assets\/?$/, '');
const url = `${backendUrl}/api/render/presign-page-assets`;

if (!orderId) {
  throw new Error(`[Presign Cover Assets] Missing orderId (hasConfig=${!!item.CONFIG}, hasCoverHtml=${typeof coverHtml === 'string' && coverHtml.length > 0}, presignUrl=${url})`);
}
if (!coverHtml || typeof coverHtml !== 'string') {
  throw new Error(`[Presign Cover Assets] Missing cover_html (orderId=${orderId}, hasConfig=${!!item.CONFIG}, presignUrl=${url})`);
}
if (!token) {
  throw new Error(`[Presign Cover Assets] Missing CONFIG.backendApiToken (orderId=${orderId}, hasConfig=${!!item.CONFIG}, hasCoverHtml=true, presignUrl=${url})`);
}

const http = this.helpers.httpRequest;
const headers = { Authorization: `Bearer ${token}` };
function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }
function jitter(max = 200) { return Math.floor(Math.random() * max); }
let lastErr = null;
for (let attempt = 1; attempt <= 3; attempt++) {
  try {
    const res = await http({ method: 'POST', url, headers, body: { html: coverHtml, expiresInSeconds: 21600 }, json: true, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    const status = Number(res?.statusCode || res?.status || 200);
    const body = res?.body !== undefined ? res.body : res;
    if (status >= 200 && status < 300 && body?.html && typeof body.html === 'string') {
      return { json: { ...item, cover_html: body.html } };
    }
    const message = body?.message || body?.error || `HTTP ${status}`;
    const transient = status === 429 || status >= 500 || status === 0;
    lastErr = new Error(String(message));
    if (attempt < 3 && transient) {
      await sleep(300 + attempt * 300 + jitter());
      continue;
    }
    break;
  } catch (e) {
    lastErr = e;
    if (attempt < 3) {
      await sleep(300 + attempt * 300 + jitter());
      continue;
    }
  }
}
throw new Error(`[Presign Cover Assets] Failed after 3 attempts (orderId=${orderId}, hasConfig=${!!item.CONFIG}, hasBackendToken=${!!token}, hasCoverHtml=${!!coverHtml}, presignUrl=${url}): ${lastErr?.message || lastErr}`);

const d=$input.item.json;
const tpl=d.CONFIG?.pdfMonkey?.coverTemplateId||'D52F14C8-BBC3-4058-929F-195DFC707E75';
if(!tpl)throw new Error('Missing coverTemplateId');
