function isUrl(value) { return typeof value === 'string' && /^https?:\/\//i.test(value); }
const now = new Date();
const amzDate = now.toISOString().replace(/[-:]/g, '').replace(/\..+/, '') + 'Z';
const date = amzDate.slice(0, 8);
const service = 's3';

function hmac(key, data) {
  return crypto.createHmac('sha256', key).update(data).digest();
}

function sha256Hex(data) {
  return crypto.createHash('sha256').update(data).digest('hex');
}

function toHex(buffer) {
  return buffer.toString('hex');
}

function buildQuery(params) {
  return Object.entries(params)
    .map(([key, value]) => encodeURIComponent(key) + '=' + encodeURIComponent(String(value)))
    .join('&');
}

function presignKey(key, expires) {
  const objectKey = encodeURIComponent(String(key).replace(/^\/+/, '')).replace(/%2F/g, '/');
  const canonicalUri = '/' + ordersBucket + '/' + objectKey;
  const credentialScope = date + '/' + region + '/' + service + '/aws4_request';
  const credential = accessKeyId + '/' + credentialScope;
  const signedHeaders = 'host';
  const queryParams = {
    'X-Amz-Algorithm': 'AWS4-HMAC-SHA256',
    'X-Amz-Credential': credential,
    'X-Amz-Date': amzDate,
    'X-Amz-Expires': String(expires),
    'X-Amz-SignedHeaders': signedHeaders,
  };
  const canonicalQueryString = buildQuery(queryParams);
  const canonicalHeaders = 'host:' + endpointHost + '\n';
  const payloadHash = 'UNSIGNED-PAYLOAD';
  const canonicalRequest = [
    'GET',
    canonicalUri,
    canonicalQueryString,
    canonicalHeaders,
    signedHeaders,
    payloadHash,
  ].join('\n');
  const stringToSign = [
    'AWS4-HMAC-SHA256',
    amzDate,
    credentialScope,
    sha256Hex(canonicalRequest),
  ].join('\n');
  const kDate = hmac(Buffer.from('AWS4' + secretAccessKey, 'utf8'), date);
  const kRegion = hmac(kDate, region);
  const kService = hmac(kRegion, service);
  const kSigning = hmac(kService, 'aws4_request');
  const signature = toHex(hmac(kSigning, stringToSign));
  return 'https://' + endpointHost + '/' + ordersBucket + '/' + objectKey + '?' + canonicalQueryString + '&X-Amz-Signature=' + signature;
}

function cleanPath(value) {
  return String(value || '').trim().split('#')[0].split('?')[0].replace(/^\/+/, '');
}

function extractAssetKey(ref) {
  if (!ref) return '';
  const raw = String(ref).trim();
  if (!raw) return '';
  if (!isUrl(raw)) return cleanPath(raw);
  if (raw.includes('/api/assets/')) {
    return cleanPath(raw.split('/api/assets/')[1] || '');
  }
  const hostMatch = raw.match(/^https?:\/\/([^/]+)/i);
  const hostname = hostMatch ? hostMatch[1] : '';
  const pathname = cleanPath(raw.replace(/^https?:\/\/[^/]+/i, ''));
  if (pathname.startsWith(ordersBucket + '/')) return pathname.slice(ordersBucket.length + 1);
  if (pathname.startsWith(publicBucket + '/')) return pathname.slice(publicBucket.length + 1);
  if (/cloudflarestorage\.com$/i.test(hostname)) return pathname;
  return '';
}

function bucketForKey(key) {
  return key.startsWith('book-mvp-simple-adventure/orders/') ? ordersBucket : publicBucket;
}

async function signPreviewRef(ref) {
  const key = extractAssetKey(ref);
  if (!key) {
    if (isUrl(ref)) return String(ref).trim();
    throw new Error('[Prepare Renderer QA Inputs] Could not derive preview key from ref: ' + String(ref));
  }
  const bucketName = bucketForKey(key);
  const query = buildQuery({ key, bucket: bucketName, expiresIn: '21600' });
  const response = await http({
    method: 'GET',
    url: backendUrl + '/api/r2/signed-url?' + query,
    headers: { Authorization: 'Bearer ' + backendToken },
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true,
    timeout: 30000,
  });
  const statusCode = Number(response?.statusCode || response?.status || 200);
  const payload = response?.body !== undefined ? response.body : response;
  if (statusCode >= 400 || !payload || typeof payload !== 'object' || !payload.url) {
    throw new Error('[Prepare Renderer QA Inputs] Failed to sign preview URL (status=' + statusCode + ', ref=' + ref + ')');
  }
  return payload.url;
}

const interiorSignedUrl = isUrl(interiorRef) ? String(interiorRef).trim() : presignKey(interiorRef, 21600);
const coverSignedUrl = isUrl(coverRef) ? String(coverRef).trim() : presignKey(coverRef, 21600);
const interiorPreviewImageUrls = [];
for (const ref of pageImageUrls) {
  interiorPreviewImageUrls.push(await signPreviewRef(ref));
}
const coverPreviewImageUrls = [await signPreviewRef(coverPreviewUrl)];

return { json: { ...item, interiorSignedUrl, coverSignedUrl, interiorPreviewImageUrls, coverPreviewImageUrls, pageLabels } };

const j = $input.item.json || {};
const supabaseProjectUrl = j.CONFIG?.supabase?.projectUrl || 'https://mdnthwpcnphjnnblbvxk.supabase.co';
