function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'string') {
      const s = v.trim();
      if (s) return s;
      continue;
    }
    return v;
  }
}

function findSiblingItems() {
  try {
    const configItems = $items('Config + Validate Sibling Group', 0, $runIndex)
      .map((entry) => entry?.json || {})
      .filter((entry) => Boolean(firstNonEmpty(entry.orderId, entry.amazonOrderId, entry.amazon_order_id)));
    if (configItems.length) return configItems;
  } catch (error) {}
  return [j];
}

const siblingItems = findSiblingItems();
const interior = j.qaInterior || {};
const cover = j.qaCover || {};
const reasons = [
  interior?.passed ? null : `interior:${interior.reasonCode || 'failed'}`,
  cover?.passed ? null : `cover:${cover.reasonCode || 'failed'}`
].filter(Boolean);
const failedPages = Array.isArray(j.qaFailedPages) ? j.qaFailedPages : [];
const errorMessage = `[W4.1 QA] Failed before Lulu submit (${reasons.join(', ') || 'unknown'}). Failed pages: ${failedPages.join(', ') || 'n/a'}`;

return siblingItems.map((sibling) => {
  const orderId = firstNonEmpty(sibling.orderId, sibling.amazonOrderId, sibling.amazon_order_id, 'unknown-order');
  return {
    json: {
