const responseItems = $input.all();
if (!responseItems.length) {
  throw new Error('[Parse Interior QA Response] Missing renderer response items');
}
let sourceItems = [];
try {
  sourceItems = $items("Guard QA Inputs", 0, $runIndex).map((entry) => entry.json || {});
} catch (error) {
  sourceItems = [];
}
return responseItems.map((entry, index) => {
  const item = sourceItems[index] || {};
  const orderId = item.orderId || item.amazonOrderId || item.amazon_order_id;
  if (!orderId) throw new Error('[Parse Interior QA Response] Missing orderId');
  const resp = entry?.json || {};
  const statusCode = Number(resp.statusCode || resp.status || 200);
  const headers = resp && typeof resp === 'object' && resp.headers && typeof resp.headers === 'object' ? resp.headers : {};
  const contentType = String(headers['content-type'] || headers['Content-Type'] || '');
  const rawBody = Object.prototype.hasOwnProperty.call(resp || {}, 'body') ? resp.body : resp;
  let payload = null;
  if (rawBody && typeof rawBody === 'object' && !Array.isArray(rawBody)) payload = rawBody;
  else if (typeof rawBody === 'string') {
    const trimmed = rawBody.trim();
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try { payload = JSON.parse(trimmed); } catch (error) {}
    }
  }
  const bodyPreview = (() => {
    try {
      return typeof rawBody === 'string' ? rawBody.slice(0, 280) : JSON.stringify(rawBody).slice(0, 280);
    } catch (error) {
      return String(rawBody).slice(0, 280);
    }
  })();
  const looksLikeProbePayload = Boolean(
    payload &&
    typeof payload === 'object' &&
    !Array.isArray(payload) &&
    Array.isArray(payload.renderedPages) &&
    typeof payload.pageCount === 'number' &&
    !Object.prototype.hasOwnProperty.call(payload, 'passed')
  );
  if (statusCode === 401 || statusCode === 403) throw new Error('[Parse Interior QA Response] Auth failure (status=' + statusCode + ', orderId=' + orderId + ', contentType=' + (contentType || 'n/a') + ', body=' + (bodyPreview || 'n/a') + ')');
  if (statusCode >= 500) throw new Error('[Parse Interior QA Response] QA renderer returned ' + statusCode + ' for orderId=' + orderId + ' (body=' + (bodyPreview || 'n/a') + ')');
  if (looksLikeProbePayload) throw new Error('[Parse Interior QA Response] Renderer returned probe payload instead of QA payload (status=' + statusCode + ', orderId=' + orderId + ', body=' + (bodyPreview || 'n/a') + ')');
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('[Parse Interior QA Response] Invalid response payload (status=' + statusCode + ', orderId=' + orderId + ', contentType=' + (contentType || 'n/a') + ', body=' + (bodyPreview || 'n/a') + ')');
  if (!Object.prototype.hasOwnProperty.call(payload, 'passed') || typeof payload.passed !== 'boolean' || !Array.isArray(payload.failedPages)) throw new Error('[Parse Interior QA Response] Invalid QA payload (status=' + statusCode + ', orderId=' + orderId + ', contentType=' + (contentType || 'n/a') + ', body=' + (bodyPreview || 'n/a') + ')');
  if (statusCode >= 400) throw new Error('[Parse Interior QA Response] Client error (status=' + statusCode + ', orderId=' + orderId + ', reason=' + (payload.reasonCode || payload.error || 'unknown') + ', body=' + (bodyPreview || 'n/a') + ')');
  const qaInterior = {
    statusCode,
    passed: payload.passed,
    skipped: false,
    reasonCode: payload.reasonCode || 'unknown',
    reason: payload.reason || 'unknown',
    failedPages: payload.failedPages,
    warnings: Array.isArray(payload.warnings) ? payload.warnings : [],
    raw: payload,
  };
  return { json: { ...item, qaInterior } };
});

